//! Thin wrappers over the few libc facilities we need. `std` already links
//! against the system C library, so the symbols are available without a crate.

use std::io::Write;

#[repr(C)]
#[derive(Default, Clone, Copy)]
struct WinSize {
    rows: u16,
    cols: u16,
    xpixel: u16,
    ypixel: u16,
}

unsafe extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
    fn signal(signum: i32, handler: usize) -> usize;
}

#[cfg(target_os = "linux")]
const TIOCGWINSZ: u64 = 0x5413;
#[cfg(not(target_os = "linux"))]
const TIOCGWINSZ: u64 = 0x40087468;

pub const SIGINT: i32 = 2;
pub const SIGTERM: i32 = 15;

/// Size of the controlling terminal, if any of the standard streams is one.
pub fn terminal_size() -> Option<(u16, u16)> {
    for fd in [1, 2, 0] {
        unsafe {
            if isatty(fd) != 1 {
                continue;
            }
            let mut ws = WinSize::default();
            if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == 0 && ws.cols > 0 {
                return Some((ws.cols, ws.rows));
            }
        }
    }
    None
}

pub fn terminal_width() -> Option<usize> {
    terminal_size().map(|(c, _)| c as usize)
}

/// Width used to lay out `--help`; clap falls back to 100 columns when there is
/// no terminal to measure.
pub fn help_width() -> usize {
    terminal_width().unwrap_or(100)
}

extern "C" fn on_interrupt(_sig: i32) {
    let mut out = std::io::stdout();
    let _ = out.write_all(b"Saving work to disk...\n");
    let _ = out.flush();
    std::process::exit(0);
}

/// Print the farewell message when the user aborts us.
pub fn install_interrupt_handler() {
    unsafe {
        signal(SIGINT, on_interrupt as usize);
        signal(SIGTERM, on_interrupt as usize);
    }
}

