//! Command line handling. The surface mirrors what a `clap`-generated parser
//! produces, down to the wording of the diagnostics and the shape of the
//! generated shell completions.

use std::time::Duration;

use crate::modules::MODULES;
use crate::term;

pub const CRATE_NAME: &str = "genact";
pub const VERSION: &str = "1.5.1";
pub const ABOUT: &str = "A nonsense activity generator";
pub const AUTHORS: &str = "Sven-Hendrik Haase <svenstaro@gmail.com>";

pub const SHELLS: [&str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

#[derive(Debug, Default)]
pub struct Options {
    pub list_modules: bool,
    pub modules: Vec<&'static str>,
    pub speed_factor: f32,
    pub instant_print_lines: u64,
    pub inhibit: bool,
    pub exit_after_time: Option<Duration>,
    pub exit_after_modules: Option<u64>,
    pub print_completions: Option<&'static str>,
    pub print_manpage: bool,
}

/// One entry in the `Options:` block of the help output.
struct ArgSpec {
    short: Option<char>,
    long: &'static str,
    value: Option<&'static str>,
    help: &'static str,
    extra: &'static str,
}

const ARGS: &[ArgSpec] = &[
    ArgSpec {
        short: Some('l'),
        long: "list-modules",
        value: None,
        help: "List available modules",
        extra: "",
    },
    ArgSpec {
        short: Some('m'),
        long: "modules",
        value: Some("MODULES"),
        help: "Run only these modules",
        extra: "modules",
    },
    ArgSpec {
        short: Some('s'),
        long: "speed-factor",
        value: Some("SPEED_FACTOR"),
        help: "Global speed factor",
        extra: "[default: 1]",
    },
    ArgSpec {
        short: Some('i'),
        long: "instant-print-lines",
        value: Some("INSTANT_PRINT_LINES"),
        help: "Instantly print this many lines",
        extra: "[default: 0]",
    },
    ArgSpec {
        short: None,
        long: "inhibit",
        value: None,
        help: "Keep the computer awake and the display on while genact is running",
        extra: "",
    },
    ArgSpec {
        short: None,
        long: "exit-after-time",
        value: Some("EXIT_AFTER_TIME"),
        help: "Exit after running for this long (format example: 2h10min)",
        extra: "",
    },
    ArgSpec {
        short: None,
        long: "exit-after-modules",
        value: Some("EXIT_AFTER_MODULES"),
        help: "Exit after running this many modules",
        extra: "",
    },
    ArgSpec {
        short: None,
        long: "print-completions",
        value: Some("shell"),
        help: "Generate completion file for a shell",
        extra: "shells",
    },
    ArgSpec {
        short: None,
        long: "print-manpage",
        value: None,
        help: "Generate man page",
        extra: "",
    },
    ArgSpec {
        short: Some('h'),
        long: "help",
        value: None,
        help: "Print help",
        extra: "",
    },
    ArgSpec {
        short: Some('V'),
        long: "version",
        value: None,
        help: "Print version",
        extra: "",
    },
];

impl ArgSpec {
    /// `-m, --modules <MODULES>` as shown in the left column of the help.
    fn invocation(&self) -> String {
        let mut s = String::new();
        match self.short {
            Some(c) => s.push_str(&format!("-{c}, ")),
            None => s.push_str("    "),
        }
        s.push_str("--");
        s.push_str(self.long);
        if let Some(v) = self.value {
            s.push_str(&format!(" <{v}>"));
        }
        s
    }

    /// The bracketed trailer clap appends after the help text.
    fn spec_vals(&self) -> String {
        match self.extra {
            "modules" => format!("[possible values: {}]", MODULES.join(", ")),
            "shells" => format!("[possible values: {}]", SHELLS.join(", ")),
            other => other.to_string(),
        }
    }

    fn usage(&self) -> String {
        let mut s = format!("--{}", self.long);
        if let Some(v) = self.value {
            s.push_str(&format!(" <{v}>"));
        }
        s
    }
}

fn bin_name() -> String {
    std::env::args()
        .next()
        .as_deref()
        .and_then(|a| a.rsplit('/').next())
        .unwrap_or(CRATE_NAME)
        .to_string()
}

fn fail(message: String, usage: Option<String>) -> ! {
    eprintln!("error: {message}");
    if let Some(u) = usage {
        eprintln!();
        eprintln!("Usage: {u}");
    }
    eprintln!();
    eprintln!("For more information, try '--help'.");
    std::process::exit(2)
}

/// Similarity metric clap uses to power its "did you mean" hints.
fn jaro(a: &str, b: &str) -> f64 {
    let x: Vec<char> = a.chars().collect();
    let y: Vec<char> = b.chars().collect();
    if x.is_empty() && y.is_empty() {
        return 1.0;
    }
    if x.is_empty() || y.is_empty() {
        return 0.0;
    }
    let window = (x.len().max(y.len()) / 2).saturating_sub(1);
    let mut x_hit = vec![false; x.len()];
    let mut y_hit = vec![false; y.len()];
    let mut matches = 0usize;
    for (i, xc) in x.iter().enumerate() {
        let lo = i.saturating_sub(window);
        let hi = (i + window + 1).min(y.len());
        for j in lo..hi {
            if !y_hit[j] && *xc == y[j] {
                x_hit[i] = true;
                y_hit[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..x.len() {
        if !x_hit[i] {
            continue;
        }
        while !y_hit[k] {
            k += 1;
        }
        if x[i] != y[k] {
            transpositions += 1;
        }
        k += 1;
    }
    let m = matches as f64;
    (m / x.len() as f64 + m / y.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let prefix = a
        .chars()
        .zip(b.chars())
        .take_while(|(x, y)| x == y)
        .count();
    (j + 0.1 * prefix as f64 * (1.0 - j)).min(1.0)
}

fn best_match<'a>(needle: &str, haystack: impl IntoIterator<Item = &'a str>) -> Option<&'a str> {
    let mut best: Option<(f64, &str)> = None;
    for candidate in haystack {
        let score = jaro_winkler(needle, candidate);
        if score > 0.7 && best.map(|(s, _)| score > s).unwrap_or(true) {
            best = Some((score, candidate));
        }
    }
    best.map(|(_, c)| c)
}

fn unexpected_argument(arg: &str) -> ! {
    let known: Vec<String> = ARGS.iter().map(|a| format!("--{}", a.long)).collect();
    let hint = best_match(arg, known.iter().map(|s| s.as_str()));
    let mut message = format!("unexpected argument '{arg}' found");
    let usage = match hint {
        Some(h) => {
            message.push_str(&format!("\n\n  tip: a similar argument exists: '{h}'"));
            let spec = ARGS.iter().find(|a| format!("--{}", a.long) == h).unwrap();
            format!("{} {}", bin_name(), spec.usage())
        }
        None => format!("{} [OPTIONS]", bin_name()),
    };
    fail(message, Some(usage))
}

fn invalid_value(spec: &ArgSpec, value: &str, reason: Option<String>, choices: &[&str]) -> ! {
    let mut message = format!("invalid value '{value}' for '{}'", spec.usage());
    if let Some(r) = reason {
        message.push_str(&format!(": {r}"));
    }
    if !choices.is_empty() {
        message.push_str(&format!("\n  [possible values: {}]", choices.join(", ")));
        if let Some(h) = best_match(value, choices.iter().copied()) {
            message.push_str(&format!("\n\n  tip: a similar value exists: '{h}'"));
        }
    }
    fail(message, None)
}

fn missing_value(spec: &ArgSpec, choices: &[&str]) -> ! {
    let mut message = format!(
        "a value is required for '{}' but none was supplied",
        spec.usage()
    );
    if !choices.is_empty() {
        message.push_str(&format!("\n  [possible values: {}]", choices.join(", ")));
    }
    fail(message, None)
}

fn spec(long: &str) -> &'static ArgSpec {
    ARGS.iter().find(|a| a.long == long).unwrap()
}

pub fn parse() -> Options {
    let mut opts = Options {
        speed_factor: 1.0,
        ..Default::default()
    };
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0;
    while i < argv.len() {
        let arg = argv[i].clone();
        let mut take_value = |name: &'static str, inline: Option<String>| -> String {
            match inline {
                Some(v) => v,
                None => {
                    i += 1;
                    match argv.get(i) {
                        Some(v) if !(v.starts_with('-') && v.len() > 1) => v.clone(),
                        _ => missing_value(spec(name), if name == "modules" { &MODULES } else { &[] }),
                    }
                }
            }
        };
        let (name, inline): (&str, Option<String>) = if let Some(rest) = arg.strip_prefix("--") {
            match rest.split_once('=') {
                Some((k, v)) => (long_name(k, &arg), Some(v.to_string())),
                None => (long_name(rest, &arg), None),
            }
        } else if arg.starts_with('-') && arg.len() >= 2 {
            let mut chars = arg.chars().skip(1);
            let c = chars.next().unwrap();
            let rest: String = chars.collect();
            let name = match ARGS.iter().find(|a| a.short == Some(c)) {
                Some(a) => a.long,
                None => unexpected_argument(&arg),
            };
            let takes_value = spec(name).value.is_some();
            if rest.is_empty() {
                (name, None)
            } else if takes_value {
                (name, Some(rest))
            } else {
                // Bundled short flags such as `-lV`.
                unexpected_argument(&arg)
            }
        } else {
            unexpected_argument(&arg)
        };

        match name {
            "list-modules" => opts.list_modules = true,
            "inhibit" => opts.inhibit = true,
            "print-manpage" => opts.print_manpage = true,
            "help" => {
                print!("{}", render_help());
                std::process::exit(0);
            }
            "version" => {
                println!("{CRATE_NAME} {VERSION}");
                std::process::exit(0);
            }
            "modules" => {
                let v = take_value("modules", inline);
                match MODULES.iter().find(|m| **m == v) {
                    Some(m) => opts.modules.push(m),
                    None => invalid_value(spec("modules"), &v, None, &MODULES),
                }
            }
            "speed-factor" => {
                let v = take_value("speed-factor", inline);
                match v.parse::<f32>() {
                    Ok(f) => opts.speed_factor = f,
                    Err(e) => invalid_value(spec("speed-factor"), &v, Some(e.to_string()), &[]),
                }
            }
            "instant-print-lines" => {
                let v = take_value("instant-print-lines", inline);
                match v.parse::<u64>() {
                    Ok(n) => opts.instant_print_lines = n,
                    Err(e) => {
                        invalid_value(spec("instant-print-lines"), &v, Some(e.to_string()), &[])
                    }
                }
            }
            "exit-after-time" => {
                let v = take_value("exit-after-time", inline);
                match parse_duration(&v) {
                    Ok(d) => opts.exit_after_time = Some(d),
                    Err(e) => invalid_value(spec("exit-after-time"), &v, Some(e), &[]),
                }
            }
            "exit-after-modules" => {
                let v = take_value("exit-after-modules", inline);
                match v.parse::<u64>() {
                    Ok(n) => opts.exit_after_modules = Some(n),
                    Err(e) => {
                        invalid_value(spec("exit-after-modules"), &v, Some(e.to_string()), &[])
                    }
                }
            }
            "print-completions" => {
                let v = take_value("print-completions", inline);
                match SHELLS.iter().find(|s| **s == v) {
                    Some(s) => opts.print_completions = Some(s),
                    None => invalid_value(spec("print-completions"), &v, None, &SHELLS),
                }
            }
            _ => unreachable!(),
        }
        i += 1;
    }
    opts
}

fn long_name(key: &str, whole: &str) -> &'static str {
    match ARGS.iter().find(|a| a.long == key) {
        Some(a) => a.long,
        None => unexpected_argument(whole),
    }
}

// ---------------------------------------------------------------- help output

fn wrap(text: &str, width: usize) -> Vec<String> {
    let width = width.max(1);
    let mut lines = Vec::new();
    let mut current = String::new();
    for word in text.split(' ') {
        if current.is_empty() {
            current.push_str(word);
        } else if current.chars().count() + 1 + word.chars().count() <= width {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(std::mem::take(&mut current));
            current.push_str(word);
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

pub fn render_help() -> String {
    let width = term::help_width();
    let entries: Vec<(String, String)> = ARGS
        .iter()
        .map(|a| {
            let mut help = a.help.to_string();
            let extra = a.spec_vals();
            if !extra.is_empty() {
                help.push(' ');
                help.push_str(&extra);
            }
            (a.invocation(), help)
        })
        .collect();
    let longest = entries.iter().map(|(i, _)| i.chars().count()).max().unwrap();

    // clap moves the help text onto its own line once the left column starts
    // eating into the available space.
    let taken = longest + 4;
    let next_line = width >= taken
        && (taken as f32 / width as f32) > 0.40
        && entries
            .iter()
            .any(|(_, h)| h.chars().count() > width - taken);

    let mut out = String::new();
    out.push_str(ABOUT);
    out.push_str("\n\n");
    out.push_str(&format!("Usage: {} [OPTIONS]\n\n", bin_name()));
    out.push_str("Options:\n");
    for (invocation, help) in &entries {
        if next_line {
            out.push_str(&format!("  {invocation}\n"));
            for line in wrap(help, width.saturating_sub(10)) {
                out.push_str(&format!("          {line}\n"));
            }
        } else {
            let pad = longest - invocation.chars().count();
            let indent = 2 + longest + 2;
            let lines = wrap(help, width.saturating_sub(indent));
            out.push_str(&format!(
                "  {invocation}{:pad$}  {}\n",
                "",
                lines[0],
                pad = pad
            ));
            for line in &lines[1..] {
                out.push_str(&format!("{:indent$}{line}\n", "", indent = indent));
            }
        }
    }
    out
}

pub fn render_manpage() -> String {
    let mut out = String::new();
    out.push_str(".ie \\n(.g .ds Aq \\(aq\n");
    out.push_str(".el .ds Aq '\n");
    out.push_str(&format!(
        ".TH {CRATE_NAME} 1  \"{CRATE_NAME} {VERSION}\" \n"
    ));
    out.push_str(".SH NAME\n");
    out.push_str(&format!("{CRATE_NAME} \\- {ABOUT}\n"));
    out.push_str(".SH SYNOPSIS\n");
    out.push_str(&format!("\\fB{CRATE_NAME}\\fR "));
    for a in ARGS {
        let mut piece = String::from("[");
        if let Some(c) = a.short {
            piece.push_str(&format!("\\fB\\-{c}\\fR|"));
        }
        piece.push_str(&format!("\\fB\\-\\-{}\\fR]", escape_roff(a.long)));
        out.push_str(&piece);
        out.push(' ');
    }
    out.push('\n');
    out.push_str(".SH DESCRIPTION\n");
    out.push_str(&format!("{ABOUT}\n"));
    out.push_str(".SH OPTIONS\n");
    for a in ARGS {
        out.push_str(".TP\n");
        let mut header = String::new();
        if let Some(c) = a.short {
            header.push_str(&format!("\\fB\\-{c}\\fR, "));
        }
        header.push_str(&format!("\\fB\\-\\-{}\\fR", escape_roff(a.long)));
        if let Some(v) = a.value {
            header.push_str(&format!(" \\fI<{}>\\fR", escape_roff(v)));
        }
        if a.extra.starts_with('[') {
            header.push_str(&format!(" {}", a.extra));
        }
        out.push_str(&header);
        out.push('\n');
        let choices: &[&str] = match a.extra {
            "modules" => &MODULES,
            "shells" => &SHELLS,
            _ => &[],
        };
        if !choices.is_empty() {
            out.push_str(".br\n\n.br\n");
            out.push_str("\\fIPossible values:\\fR\n");
            out.push_str(".RS 14\n");
            for c in choices {
                out.push_str(".IP \\(bu 2\n");
                out.push_str(&format!("{}\n", escape_roff(c)));
            }
            out.push_str(".RE\n");
        }
        out.push_str(&format!("{}\n", escape_roff(a.help)));
    }
    out.push_str(".SH VERSION\n");
    out.push_str(&format!("v{VERSION}\n"));
    out.push_str(".SH AUTHORS\n");
    out.push_str(&format!("{}\n", escape_roff(AUTHORS)));
    out
}

fn escape_roff(s: &str) -> String {
    s.replace('\\', "\\\\").replace('-', "\\-")
}

pub fn render_completions(shell: &str) -> String {
    let modules = MODULES.join(" ");
    let shells = SHELLS.join(" ");
    match shell {
        "bash" => bash_completions(&modules, &shells),
        "zsh" => zsh_completions(&modules, &shells),
        "fish" => fish_completions(),
        "elvish" => elvish_completions(),
        _ => powershell_completions(),
    }
}

fn bash_completions(modules: &str, shells: &str) -> String {
    let value_args = [
        ("--modules", Some(modules)),
        ("-m", Some(modules)),
        ("--speed-factor", None),
        ("-s", None),
        ("--instant-print-lines", None),
        ("-i", None),
        ("--exit-after-time", None),
        ("--exit-after-modules", None),
        ("--print-completions", Some(shells)),
    ];
    let mut cases = String::new();
    for (flag, values) in value_args {
        cases.push_str(&format!("                {flag})\n"));
        match values {
            Some(v) => cases.push_str(&format!(
                "                    COMPREPLY=($(compgen -W \"{v}\" -- \"${{cur}}\"))\n"
            )),
            None => cases
                .push_str("                    COMPREPLY=($(compgen -f \"${cur}\"))\n"),
        }
        cases.push_str("                    return 0\n                    ;;\n");
    }
    let opts = "-l -m -s -i -h -V --list-modules --modules --speed-factor --instant-print-lines --inhibit --exit-after-time --exit-after-modules --print-completions --print-manpage --help --version";
    format!(
        r#"_genact() {{
    local i cur prev opts cmd
    COMPREPLY=()
    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
        cur="$2"
    else
        cur="${{COMP_WORDS[COMP_CWORD]}}"
    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${{COMP_WORDS[@]:0:COMP_CWORD}}"
    do
        case "${{cmd}},${{i}}" in
            ",$1")
                cmd="genact"
                ;;
            *)
                ;;
        esac
    done

    case "${{cmd}}" in
        genact)
            opts="{opts}"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
{cases}                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
    esac
}}

if [[ "${{BASH_VERSINFO[0]}}" -eq 4 && "${{BASH_VERSINFO[1]}}" -ge 4 || "${{BASH_VERSINFO[0]}}" -gt 4 ]]; then
    complete -F _genact -o nosort -o bashdefault -o default genact
else
    complete -F _genact -o bashdefault -o default genact
fi
"#
    )
}

fn zsh_completions(modules: &str, shells: &str) -> String {
    let mut lines = String::new();
    lines.push_str(&format!(
        "'*-m+[Run only these modules]:MODULES:({modules})' \\\n"
    ));
    lines.push_str(&format!(
        "'*--modules=[Run only these modules]:MODULES:({modules})' \\\n"
    ));
    lines.push_str("'-s+[Global speed factor]:SPEED_FACTOR:_default' \\\n");
    lines.push_str("'--speed-factor=[Global speed factor]:SPEED_FACTOR:_default' \\\n");
    lines.push_str("'-i+[Instantly print this many lines]:INSTANT_PRINT_LINES:_default' \\\n");
    lines.push_str(
        "'--instant-print-lines=[Instantly print this many lines]:INSTANT_PRINT_LINES:_default' \\\n",
    );
    lines.push_str("'--exit-after-time=[Exit after running for this long (format example\\: 2h10min)]:EXIT_AFTER_TIME:_default' \\\n");
    lines.push_str(
        "'--exit-after-modules=[Exit after running this many modules]:EXIT_AFTER_MODULES:_default' \\\n",
    );
    lines.push_str(&format!(
        "'--print-completions=[Generate completion file for a shell]:shell:({shells})' \\\n"
    ));
    lines.push_str("'-l[List available modules]' \\\n");
    lines.push_str("'--list-modules[List available modules]' \\\n");
    lines.push_str(
        "'--inhibit[Keep the computer awake and the display on while genact is running]' \\\n",
    );
    lines.push_str("'--print-manpage[Generate man page]' \\\n");
    lines.push_str("'-h[Print help]' \\\n");
    lines.push_str("'--help[Print help]' \\\n");
    lines.push_str("'-V[Print version]' \\\n");
    lines.push_str("'--version[Print version]' \\\n");
    format!(
        r#"#compdef genact

autoload -U is-at-least

_genact() {{
    typeset -A opt_args
    typeset -a _arguments_options
    local ret=1

    if is-at-least 5.2; then
        _arguments_options=(-s -S -C)
    else
        _arguments_options=(-s -C)
    fi

    local context curcontext="$curcontext" state line
    _arguments "${{_arguments_options[@]}}" : \
{lines}&& ret=0
}}

(( $+functions[_genact_commands] )) ||
_genact_commands() {{
    local commands; commands=()
    _describe -t commands 'genact commands' commands "$@"
}}

if [ "$funcstack[1]" = "_genact" ]; then
    _genact "$@"
else
    compdef _genact genact
fi
"#
    )
}

fn fish_value_list(values: &[&str]) -> String {
    values
        .iter()
        .map(|v| format!("{v}\\t''"))
        .collect::<Vec<_>>()
        .join("\n")
}

fn fish_completions() -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "complete -c genact -s m -l modules -d 'Run only these modules' -r -f -a \"{}\"\n",
        fish_value_list(&MODULES)
    ));
    out.push_str("complete -c genact -s s -l speed-factor -d 'Global speed factor' -r\n");
    out.push_str(
        "complete -c genact -s i -l instant-print-lines -d 'Instantly print this many lines' -r\n",
    );
    out.push_str("complete -c genact -l exit-after-time -d 'Exit after running for this long (format example: 2h10min)' -r\n");
    out.push_str(
        "complete -c genact -l exit-after-modules -d 'Exit after running this many modules' -r\n",
    );
    out.push_str(&format!(
        "complete -c genact -l print-completions -d 'Generate completion file for a shell' -r -f -a \"{}\"\n",
        fish_value_list(&SHELLS)
    ));
    out.push_str("complete -c genact -s l -l list-modules -d 'List available modules'\n");
    out.push_str("complete -c genact -l inhibit -d 'Keep the computer awake and the display on while genact is running'\n");
    out.push_str("complete -c genact -l print-manpage -d 'Generate man page'\n");
    out.push_str("complete -c genact -s h -l help -d 'Print help'\n");
    out.push_str("complete -c genact -s V -l version -d 'Print version'\n");
    out
}

/// The flags in the order the completion generators emit them: options that
/// take a value first, then the plain switches.
const COMPLETION_ORDER: [(&str, &str, &str); 17] = [
    ("-m", "--modules", "Run only these modules"),
    ("", "--modules", "Run only these modules"),
    ("-s", "--speed-factor", "Global speed factor"),
    ("", "--speed-factor", "Global speed factor"),
    ("-i", "--instant-print-lines", "Instantly print this many lines"),
    ("", "--instant-print-lines", "Instantly print this many lines"),
    (
        "",
        "--exit-after-time",
        "Exit after running for this long (format example: 2h10min)",
    ),
    (
        "",
        "--exit-after-modules",
        "Exit after running this many modules",
    ),
    (
        "",
        "--print-completions",
        "Generate completion file for a shell",
    ),
    ("-l", "--list-modules", "List available modules"),
    ("", "--list-modules", "List available modules"),
    (
        "",
        "--inhibit",
        "Keep the computer awake and the display on while genact is running",
    ),
    ("", "--print-manpage", "Generate man page"),
    ("-h", "--help", "Print help"),
    ("", "--help", "Print help"),
    ("-V", "--version", "Print version"),
    ("", "--version", "Print version"),
];

fn elvish_completions() -> String {
    let mut cands = String::new();
    for (short, long, help) in COMPLETION_ORDER {
        let flag = if short.is_empty() { long } else { short };
        cands.push_str(&format!("            cand {flag} '{help}'\n"));
    }
    format!(
        r#"
use builtin;
use str;

set edit:completion:arg-completer[genact] = {{|@words|
    fn spaces {{|n|
        builtin:repeat $n ' ' | str:join ''
    }}
    fn cand {{|text desc|
        edit:complex-candidate $text &display=$text' '(spaces (- 14 (wcswidth $text)))$desc
    }}
    var command = 'genact'
    for word $words[1..-1] {{
        if (str:has-prefix $word '-') {{
            break
        }}
        set command = $command';'$word
    }}
    var completions = [
        &'genact'= {{
{cands}        }}
    ]
    $completions[$command]
}}
"#
    )
}

fn powershell_completions() -> String {
    let mut cands = String::new();
    for (short, long, help) in COMPLETION_ORDER {
        let flag = if short.is_empty() { long } else { short };
        // clap pads the insert text of the final short flag.
        let insert = if flag == "-V" { "-V " } else { flag };
        cands.push_str(&format!(
            "            [CompletionResult]::new('{flag}', '{insert}', [CompletionResultType]::ParameterName, '{help}')\n"
        ));
    }
    format!(
        r#"
using namespace System.Management.Automation
using namespace System.Management.Automation.Language

Register-ArgumentCompleter -Native -CommandName 'genact' -ScriptBlock {{
    param($wordToComplete, $commandAst, $cursorPosition)

    $commandElements = $commandAst.CommandElements
    $command = @(
        'genact'
        for ($i = 1; $i -lt $commandElements.Count; $i++) {{
            $element = $commandElements[$i]
            if ($element -isnot [StringConstantExpressionAst] -or
                $element.StringConstantType -ne [StringConstantType]::BareWord -or
                $element.Value.StartsWith('-') -or
                $element.Value -eq $wordToComplete) {{
                break
        }}
        $element.Value
    }}) -join ';'

    $completions = @(switch ($command) {{
        'genact' {{
{cands}            break
        }}
    }})

    $completions.Where{{ $_.CompletionText -like "$wordToComplete*" }} |
        Sort-Object -Property ListItemText
}}
"#
    )
}

// ------------------------------------------------------------ duration syntax

const UNITS: &[(&str, u64)] = &[
    ("nsec", 1),
    ("ns", 1),
    ("usec", 1_000),
    ("us", 1_000),
    ("\u{b5}sec", 1_000),
    ("\u{b5}s", 1_000),
    ("msec", 1_000_000),
    ("ms", 1_000_000),
    ("seconds", 1_000_000_000),
    ("second", 1_000_000_000),
    ("secs", 1_000_000_000),
    ("sec", 1_000_000_000),
    ("s", 1_000_000_000),
    ("minutes", 60_000_000_000),
    ("minute", 60_000_000_000),
    ("mins", 60_000_000_000),
    ("min", 60_000_000_000),
    ("m", 60_000_000_000),
    ("hours", 3_600_000_000_000),
    ("hour", 3_600_000_000_000),
    ("hrs", 3_600_000_000_000),
    ("hr", 3_600_000_000_000),
    ("h", 3_600_000_000_000),
    ("days", 86_400_000_000_000),
    ("day", 86_400_000_000_000),
    ("d", 86_400_000_000_000),
    ("weeks", 604_800_000_000_000),
    ("week", 604_800_000_000_000),
    ("w", 604_800_000_000_000),
    ("months", 2_630_016_000_000_000),
    ("month", 2_630_016_000_000_000),
    ("M", 2_630_016_000_000_000),
    ("years", 31_557_600_000_000_000),
    ("year", 31_557_600_000_000_000),
    ("y", 31_557_600_000_000_000),
];

const UNIT_HELP: &str =
    "supported units: ns, us/\u{b5}s, ms, sec, min, hours, days, weeks, months, years (and few variations)";

pub fn parse_duration(text: &str) -> Result<Duration, String> {
    let chars: Vec<char> = text.chars().collect();
    if chars.iter().all(|c| c.is_whitespace()) {
        return Err("value was empty".to_string());
    }
    let mut total_nanos: u128 = 0;
    let mut i = 0usize;
    loop {
        while i < chars.len() && chars[i].is_whitespace() {
            i += 1;
        }
        if i >= chars.len() {
            break;
        }
        let start = i;
        while i < chars.len() && chars[i].is_ascii_digit() {
            i += 1;
        }
        if i == start {
            return Err(format!("expected number at {start}"));
        }
        let mut number: String = chars[start..i].iter().collect();
        if i < chars.len() && chars[i] == '.' {
            let dot = i;
            i += 1;
            let frac_start = i;
            while i < chars.len() && chars[i].is_ascii_digit() {
                i += 1;
            }
            if i == frac_start {
                return Err(format!("invalid character at {dot}"));
            }
            number.push('.');
            number.extend(chars[frac_start..i].iter());
        }
        while i < chars.len() && chars[i].is_whitespace() {
            i += 1;
        }
        let unit_start = i;
        while i < chars.len() && chars[i].is_alphabetic() {
            i += 1;
        }
        if i == unit_start {
            return Err(format!(
                "time unit needed, for example {number}sec or {number}ms"
            ));
        }
        let unit: String = chars[unit_start..i].iter().collect();
        let multiplier = match UNITS.iter().find(|(u, _)| *u == unit) {
            Some((_, m)) => *m,
            None => {
                // humantime reports only the first offending character.
                let first: String = unit.chars().next().into_iter().collect();
                return Err(format!("unknown time unit \"{first}\", {UNIT_HELP}"));
            }
        };
        let value: f64 = number.parse().map_err(|_| too_large())?;
        let nanos = value * multiplier as f64;
        if !nanos.is_finite() || nanos >= u64::MAX as f64 * 1.0e9 {
            return Err(too_large());
        }
        total_nanos += nanos.round() as u128;
        if total_nanos > u64::MAX as u128 * 1_000_000_000 {
            return Err(too_large());
        }
    }
    Ok(Duration::new(
        (total_nanos / 1_000_000_000) as u64,
        (total_nanos % 1_000_000_000) as u32,
    ))
}

fn too_large() -> String {
    "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string()
}

