//! Output primitives shared by every scene: paced printing, the global speed
//! knob and the "instantly print N lines" fast-forward.

use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::{Duration, Instant};
use std::sync::OnceLock;

use crate::term;

static SPEED_FACTOR: AtomicU64 = AtomicU64::new(1_000);
static INSTANT_LINES: AtomicU64 = AtomicU64::new(0);
static DEADLINE_SET: AtomicBool = AtomicBool::new(false);

static STARTED: OnceLock<Instant> = OnceLock::new();
static DEADLINE: OnceLock<Duration> = OnceLock::new();

pub fn configure(speed_factor: f32, instant_print_lines: u64, exit_after_time: Option<Duration>) {
    let factor = if speed_factor.is_finite() && speed_factor > 0.0 {
        speed_factor
    } else {
        1.0
    };
    SPEED_FACTOR.store((factor as f64 * 1_000.0) as u64, Ordering::Relaxed);
    INSTANT_LINES.store(instant_print_lines, Ordering::Relaxed);
    let _ = STARTED.set(Instant::now());
    if let Some(d) = exit_after_time {
        let _ = DEADLINE.set(d);
        DEADLINE_SET.store(true, Ordering::Relaxed);
    }
}

/// True when the caller should skip its delay because we are fast-forwarding.
fn consume_instant() -> bool {
    let mut current = INSTANT_LINES.load(Ordering::Relaxed);
    while current > 0 {
        match INSTANT_LINES.compare_exchange_weak(
            current,
            current - 1,
            Ordering::Relaxed,
            Ordering::Relaxed,
        ) {
            Ok(_) => return true,
            Err(actual) => current = actual,
        }
    }
    false
}

fn check_deadline() {
    if !DEADLINE_SET.load(Ordering::Relaxed) {
        return;
    }
    if let (Some(start), Some(limit)) = (STARTED.get(), DEADLINE.get()) {
        if start.elapsed() >= *limit {
            crate::finish();
        }
    }
}

/// Sleep for `millis` scaled by the global speed factor.
pub fn csleep(millis: u64) {
    check_deadline();
    if consume_instant() {
        return;
    }
    let factor = SPEED_FACTOR.load(Ordering::Relaxed) as f64 / 1_000.0;
    let secs = millis as f64 / 1_000.0 / factor;
    if secs > 0.0 {
        std::thread::sleep(Duration::from_secs_f64(secs));
    }
    check_deadline();
}

pub fn print_str(text: &str) {
    let mut out = std::io::stdout().lock();
    if out.write_all(text.as_bytes()).is_err() {
        std::process::exit(0);
    }
    let _ = out.flush();
}

/// Print `text` and wait afterwards, the way a slow console would.
pub fn dprint(text: impl AsRef<str>, delay: u64) {
    print_str(text.as_ref());
    if delay > 0 {
        csleep(delay);
    }
}

/// Terminals are in raw-ish mode, so every line break needs the carriage return.
pub fn newline() {
    print_str("\r\n");
}

/// Print a whole line followed by a pause.
pub fn dprintln(text: impl AsRef<str>, delay: u64) {
    print_str(text.as_ref());
    newline();
    if delay > 0 {
        csleep(delay);
    }
}

pub fn erase_line() {
    print_str("\r\x1b[2K");
}

pub fn cursor_up(n: usize) {
    print_str(&format!("\x1b[{n}A"));
}

pub fn hide_cursor() {
    print_str("\x1b[?25l");
}

pub fn show_cursor() {
    print_str("\x1b[?25h");
}

/// Width of the attached terminal. Several scenes lay their output out in
/// columns and simply cannot work without knowing it.
pub fn get_terminal_width() -> usize {
    match term::terminal_width() {
        Some(w) => w,
        None => {
            eprintln!();
        panic!("Couldn't get terminal width. Is an interactive terminal attached?")
        }
    }
}

